city("xiamen", "厦门",
 [P("船票","鼓浪屿轮渡需提前 1-3 天在“厦门轮渡”小程序购票，游客从东渡邮轮中心/嵩屿码头出发，节假日当天基本无票"),
  P("季节","夏秋台风季关注预报；4-5 月与 10-11 月气候最舒适；冬季温暖可下海边走走"),
  P("环岛交通","环岛路、厦大片区骑共享单车/电动车最自由；白城沙滩段骑行是厦门精华体验"),
  P("住宿选址","中山路-八市片区烟火气与交通便利；曾厝垵文艺但嘈杂；鼓浪屿岛上住一晚体验清晨无人街巷"),
  P("行程结构","厦门本岛 2 天（环岛路+厦大沙坡尾+八市）+ 鼓浪屿 1 天是黄金配比，别把行程排满留时间看海")],
 [S("鼓浪屿","思明区","必去","一天","轮渡 35 元往返起，岛上全步行无机动车：日光岩俯瞰全岛、菽庄花园借海入园、风琴博物馆；核心景点联票 90（参考）；避开 10-16 点旅行团高峰，住岛上看清晨的空街最值"),
  S("厦门大学·南普陀寺","思明区","经典","半天","厦大入校需预约（以官方渠道为准），芙蓉隧道涂鸦与上弦场是打卡点；南普陀免费，寺后五老峰爬 40 分钟可俯瞰厦大与海"),
  S("环岛路·白城沙滩","思明区","经典","半天","从厦大白城骑到会展中心约 1 小时海岸线，椰风寨、音乐广场处处可停；“一国两制”标语沙滩对望金门；日落时分最美"),
  S("沙坡尾·艺术西区","思明区","小众","2-3小时","避风坞渔港变身文艺街区，旧船、老骑楼与买手店混搭；附近猫街、顶澳仔适合拍照，傍晚顺路演武大桥观景平台看海"),
  S("八市（第八市场）","思明区开元路","小众","2小时","老厦门的海鲜市场与市井烟火，阿吉仔馅饼、友生风味小吃都在此；早市最鲜活，下午来适合边逛边吃"),
  S("中山路步行街","思明区","经典","2-3小时","南洋骑楼建筑群，晚上亮灯；往两侧巷子（大中路、局口街）钻，小吃性价比高于主街；黄则和花生汤是老字号甜口"),
  S("曾厝垵","思明区","经典","2-3小时","“最文艺渔村”商业浓但夜市热闹，海鲜排档与文创小店密集；作为环岛路途中的歇脚点合适，专程去则预期放低"),
  S("集美学村·龙舟池","集美区","小众","半天","嘉庚建筑“穿西装戴斗笠”，石板路与红砖楼安静上镜；地铁 1 号线跨海段本身是景观，高集海堤看地铁穿海"),
  S("山海健康步道","思明区","小众","2-3小时","空中步道串联狐尾山、仙岳山，看城市与海的全景视角；免费，入口多可按体力选择段落，傍晚光线最佳"),
  S("五缘湾·帆船出海","湖里区","亲子","半天","帆船体验约 100-200/人（参考），运气好能遇白海豚；湿地公园黑天鹅与木栈道适合遛娃")],
 [F("沙茶面","乌糖/月华/八市老店","汤头是灵魂——沙茶酱与花生酱熬制浓郁微甜，自选加料（豆腐泡、鸭腱、猪肝沿）"),
  F("海蛎煎","八市/莲欢海蛎煎","闽南“蚵仔煎”，地瓜粉浆裹鲜蚝外酥内软蘸甜辣酱；莲欢在八市里，营业到下午"),
  F("姜母鸭","阿呆/津品老店","砂锅老姜麻油焖制，焦香扑鼻；一锅两人食，配白饭刚好"),
  F("土笋冻","西门/五兰","沙虫熬煮凝冻配蒜蓉酱油芥末，口感弹脆；外地人口关难越，试一次不亏"),
  F("花生汤+油条","黄则和","花生炖到化渣甜而不腻，冲蛋花生汤是隐藏菜单；中山路老店配油条豆浆当早餐"),
  F("烧肉粽","1980烧肉粽","卤肉香菇虾米蛋黄全包进糯米，蘸沙茶酱或甜辣酱；当下午茶或宵夜都合适"),
  F("面线糊","阿芬/李菊英","细面线糊汤加醋肉大肠海鲜自选，撒胡椒香菜，厦门人的早餐与深夜食堂"),
  F("海鲜加工","小眼镜大排档","自购海鲜找加工或直接点，先问时价；本港小管（鱿鱼）白灼最鲜，季节性强")],
 [T("BRT/地铁","1/2/3 号线","1 号线跨海段看海，2 号线到五缘湾；BRT 高架快线覆盖岛内外主要节点"),
  T("轮渡","东渡/嵩屿码头→鼓浪屿","游客航线须从这两个码头出发（35 元往返起，参考）；厦大附近的轮渡码头基本为市民航线"),
  T("机场","高崎机场","地铁 1 号线直达，岛内 30 分钟内；T3/T4 航站楼看清再出发"),
  T("骑行","环岛路","白城沙滩沿线共享单车充足，骑至曾厝垵/黄厝一段最经典；注意海风与行人"),
  T("跨城","高铁厦门北站","进岛约 1 小时；去泉州 30 分钟、潮汕 1.5 小时，适合串联闽南线")],
 [W("船票","鼓浪屿上岛船票务必提前 1-3 天购买，节假日连往返票都紧张；码头上“代购”加价勿信"),
  W("海鲜花蟹","点单先问价、复述单价重量再下单，避免时价纠纷；排档“推荐菜”可能是高毛利菜"),
  W("台风","7-9 月台风季关注预警，轮渡与航班随时停航，行程留弹性"),
  W("厦大预约","校园预约名额紧张且有参观时段限制，别把当天行程押在厦大上；南普陀无需预约可先行"),
  W("鼓浪屿攻略","岛上拉客导游与“免排队套票”多为消费返点套路，核心五景联票官方渠道即可"),
  W("防晒","海边紫外线强，骑行与沙滩务必防晒；夏季下午 2-4 点尽量室内")],
 [B("住宿","300-600/晚（中山路/曾厝垵，鼓浪屿民宿 400+）"),
  B("餐饮","80-150/天（海鲜正餐人均 100-200）"),
  B("门票","鼓浪屿核心联票 90、轮渡 35 起（参考）"),
  B("交通","地铁/BRT 2-6 元/程、帆船 100-200"),
  B("伴手礼","馅饼/肉松 30-80（参考）")])

