city("huangshan", "黄山",
 [P("装备","登山杖、防滑鞋、雨衣（山上风大伞无用）；山顶昼夜温差 10℃+，即使夏季也要带外套"),
  P("预约","旺季需预约入园与索道票，官方“黄山旅游官方平台”小程序购票；看日出建议住山顶酒店，价格高需提前数周订"),
  P("体力预算","后山上前山下下是省力经典线：云谷索道上—始信峰—光明顶—玉屏索道下，全程 6-8 小时徒步"),
  P("季节","4-6 月云海频发、9-10 月秋色、12-2 月雾凇雪景+冬游票价下浮；雨天雾大看不见景但出人像"),
  P("联游","山下宏村西递各半天，屯溪老街当晚可逛；黄山北站高铁直达")],
 [S("黄山风景区","黄山市","必去","1-2天","奇松怪石云海温泉四绝：始信峰看黑龙松、猴子观海在狮子峰、飞来石与光明顶是中段枢纽、迎客松在玉屏楼；西海大峡谷“一环二环”栈道悬空刺激（冬季关闭）；两日游建议住北海或西海饭店区域，日出在丹霞峰/清凉台看"),
  S("宏村","黟县","经典","半天","牛形村落，月沼与南湖是水墨画原版，承志堂木雕“民间故宫”；写生学生满巷是日常；清晨与日落后团队散去最出片，村口无数家饭店但景区内贵"),
  S("西递","黟县","小众","半天","比宏村安静，胡文光牌坊、追慕堂与深巷保存原味；“桃花源里人家”牌匾在村口；与宏村二选一或连游皆可，联游有联票"),
  S("屯溪老街","屯溪区","经典","2-3小时","活动着的“清明上河图”，徽墨歙砚、黄山烧饼、茶叶店密集；黎阳in巷一桥之隔是新式酒吧街，新旧对比很有意思"),
  S("翡翠谷（情人谷）","黄山区汤口","小众","半天","《卧虎藏龙》竹林打斗取景地，彩池群水色如翡翠；夏季清凉避暑，与黄山南大门顺路"),
  S("新安江山水画廊","歙县","小众","半天","乘船看两岸徽派村落与油菜花（3 月），樟潭千年古樟；从屯溪自驾/包车 1 小时，适合深度徽州线"),
  S("呈坎","徽州区","小众","2-3小时","“游呈坎一生无坎”的八卦村，宝纶阁明代木构精美；游客少商业化低，老人晒秋的屋檐是人文摄影素材"),
  S("棠樾牌坊群·鲍家花园","歙县","小众","2-3小时","七座明清牌坊一字排开，“忠孝节义”石雕史诗；鲍家花园徽派盆景精巧；车程约 30 分钟，徽文化深度线"),
  S("渔梁坝·歙县古城","歙县","小众","半天","“江南都江堰”明代渔梁坝，练江水漫坝面如白练；徽州古城许国石坊八角牌楼全国独一份；车程 40 分钟")],
 [F("臭鳜鱼","屯溪徽菜馆（老街一楼/美食人家）","闻着臭吃着香是腌制发酵的功劳，筷子一拨蒜瓣肉；点鱼前问清按条计价"),
  F("毛豆腐","老街小馆/街边煎摊","发酵长绒毛的豆腐油煎后蘸辣酱，口感绵密；徽州人的“奶酪”，勇者美味"),
  F("黄山烧饼","老街各家","梅干菜猪肉馅酥饼，刚出炉的最好；认准现烤门店，真空装当手信"),
  F("徽州一刀面/石头粿","老街早餐店","手工面配笋干肉丝浇头，石头粿是徽州早点碳水之王"),
  F("一品锅","绩溪/黟县农家","层层叠码的干笋红烧肉豆腐包大杂烩，胡适先生的家乡菜，冬季吃了浑身暖"),
  F("茶体验","谢裕大/老街茶行","黄山毛峰、太平猴魁、祁门红茶三大名茶，先试后买，明前茶认准等级"),
  F("徽州圆子/茶叶蛋","屯溪老街小吃","山粉圆子烧肉是徽州家常硬菜；老街茶楼的五香茶叶蛋配茶水坐半晌"),
  F("徽墨酥/五城茶干","伴手礼铺","徽墨酥乌黑油润入口即化（名字来自徽墨形状）；五城茶干豆香耐嚼，配茶下酒皆宜")],
 [T("高铁","黄山北站","合福高铁枢纽：合肥 2 小时、上海 3 小时；北站有班车/公交到汤口换乘中心约 1 小时"),
  T("索道","云谷/玉屏/太平索道","旺季排队 1 小时+，建议 7 点前到换乘中心；索道末班约 16:30-17:00，下山别拖"),
  T("景交","汤口换乘中心","私家车不能上景区，必须在换乘中心换景区大巴（19 元/程，参考）到索道站"),
  T("县际交通","黟县/歙县班车","屯溪到宏村、西递有班车但班次少，2-4 人包车更划算（单程约 100-150，参考）")],
 [W("天气","山顶多雾，看日出需运气（概率约五成）；雷雨大风索道可能停运，行程留弹性并买好退改票"),
  W("物价","山上物资靠挑夫人力运，矿泉水 10 元、泡面 25 元属正常，自带干粮与水能省不少"),
  W("住宿","山顶酒店标准间旺季 800-1500 且需提前数周订，独卫房型紧俏；山下汤口住宿便宜且可轻装上山"),
  W("体力","西海大峡谷上下耗 3 小时且台阶陡，体力一般者走一环折返；老人小孩避开正午暴晒时段"),
  W("门票","门票两日有效但需首次入园时登记；索道票单程 80（参考）且旺季建议提前线上购"),
  W("雾天拍照","雾大时拍近景（松、石、人像）而非远景；雨后初晴最容易出云海大片"),
  W("装备租赁","防滑钉（冬季）、雨衣、登山杖汤口镇与换乘中心都有租售，登山杖 10-20 元（参考）；山顶酒店可租羽绒服"),
  W("联游节奏","黄山+宏村+屯溪 3 天 2 晚是黄金配置；黄山下来第二天逛宏村腿会酸，把西递/老街等轻量行程放最后")],
 [B("住宿","山下 200-400/晚、山顶 600-1500/晚（参考）"),
  B("餐饮","80-150/天（山上物价翻倍）"),
  B("门票","黄山旺季 190+索道 80/程、宏村 94（参考）"),
  B("交通","换乘大巴 19/程、包车 100-150/程（参考）"),
  B("体验","西海大峡谷地轨缆车 100（参考）")])

