  S("束河古镇","古城区","小众","半天","比大研安静的原味古镇，青龙桥、九鼎龙潭泉水清冽；茶马古道博物馆小而精；咖啡馆与手作店密集适合发呆"),
  S("白沙古镇","玉龙县","小众","2-3小时","纳西文化发源地，白沙壁画（明代壁画精品）与扎染小院；玉龙雪山就在正前方，田园雪山同框；商业化最低"),
  S("泸沽湖","宁蒗县","经典","2天","车程 4 小时+，环湖住里格或大落水一晚；猪槽船划到王妃岛，女神湾日落与情人滩；摩梭家访走婚文化讲解先问清是否收费"),
  S("拉市海","玉龙县","小众","半天","候鸟湿地+茶马古道骑马体验；骑马与划船套餐 100-300 元（参考），务必选正规马场并谈清路线时长；冬季看候鸟"),
  S("观音峡","玉龙县","小众","半天","峡谷栈道+玻璃桥+瀑布，车程 40 分钟的顺路半日；与机场同方向，离开前顺路玩"),
  S("黑龙潭公园","古城区","小众","2小时","玉龙雪山倒影经典机位（晴天上午），东巴文化研究院在园内；凭古维费入园"),
  S("玉湖村·洛克旧居","玉龙县","小众","半天","雪山脚下的石头村落，探险家洛克曾长住于此；骑马穿村到玉湖，雪山与村落同框人少出片"),
