  F("不翻汤","十字街夜市","绿豆薄饼不翻+酸汤夜市名物；刘记不翻汤老店排队"),
  F("牡丹饼/银条","伴手礼","牡丹花入馅的酥饼与洛阳银条（酱菜）当手信；全福食品老字号"),
