  S("雅丹魔鬼城","敦煌市","小众","一天","西线压轴：风蚀雅丹群在戈壁落日下如外星地貌，与玉门关、汉长城、阳关拼成包车一日（约 300-500/车，参考）；单程 180 公里，日落场返程夜路注意安全"),
