  W("辣度","湘菜辣度直逼川湘之最，不能吃辣点单明确“不辣”，夜宵摊默认重辣"),
  W("夜噪","解放西一带酒吧夜宵到凌晨 3 点，浅眠者选五一广场北侧或地铁沿线安静小区"),
  W("省博预约","湖南博物院免费票节假日极难约，提前 5-7 天准点抢；未约到可去长沙博物馆（同水准免预约）"),
