  F("朝鲜族冷面/锅包肉","二道白河镇","延边风味顺路：冰爽冷面配锅包肉是长白山下标准餐"),
  F("山野菜/林蛙","镇上餐馆","刺嫩芽、猴腿菜等山野菜春季最鲜；林蛙（雪蛤）按需尝试"),
